mapper.select:
select f.fact_id factId,f.project_id projectId,p.project_name projectName,p.project_no projectNo,
  f.company_dept_id companyDeptId,d.dept_name companyName,f.biz_date bizDate,f.category_id categoryId,
  f.category_code categoryCode,f.category_name categoryName,f.fact_kind factKind,f.amount,f.quantity,
  f.currency,f.unit,f.description,f.counterparty,f.attachment_urls attachmentUrls,f.source_domain sourceDomain,
  f.source_type sourceType,f.status,f.reversal_fact_id reversalFactId,f.version,
  f.confirmed_user_name confirmedUserName,f.confirmed_time confirmedTime,f.create_user_id createUserId,
  f.create_by createBy,f.create_time createTime,
  p.initiator_name initiatorName
from biz_operating_fact f join biz_project p on p.project_id=f.project_id and p.del_flag='0'
left join sys_dept d on d.dept_id=f.company_dept_id

  p.initiator_user_id=#{userId}
  and f.project_id=#{projectId}
  and f.fact_id=#{factId}
  and f.company_dept_id=#{companyDeptId}
  and f.status=#{status}
  and f.biz_date>=#{dateFrom}
  and f.biz_date<=#{dateTo}

order by f.biz_date desc,f.fact_id desc

mapper.update:
update biz_operating_fact set status='CONFIRMED',confirmed_user_id=#{userId},confirmed_user_name=#{userName},
  confirmed_time=sysdate(),update_by=#{userName},update_time=sysdate(),version=version+1
where fact_id=#{factId} and status='DRAFT' and version=#{version}

mapper.select:
select coalesce((select sum(amount) from biz_operating_fact where project_id=#{projectId}
  and biz_date<=#{bizDate} and fact_kind='COST' and status in('CONFIRMED','REVERSED')),0)
  +coalesce((select sum(personnel_cost) from biz_project_daily_result where project_id=#{projectId}
  and biz_date<=#{bizDate} and is_current='1'),0)

select r.result_id resultId,r.project_id projectId,p.project_name projectName,p.project_no projectNo,
  r.company_dept_id companyDeptId,d.dept_name companyName,r.biz_date bizDate,r.accounting_mode accountingMode,
  r.revenue_amount revenueAmount,r.cost_amount costAmount,r.personnel_cost personnelCost,
  r.adjustment_amount adjustmentAmount,r.profit_amount profitAmount,r.budget_spent budgetSpent,
  r.value_score valueScore,r.data_cutoff_time dataCutoffTime,r.close_status closeStatus,r.result_version resultVersion,
  r.calculation_detail calculationDetail,p.budget_limit budgetLimit,p.initiator_name initiatorName,p.base_currency currency
from biz_project_daily_result r join biz_project p on p.project_id=r.project_id and p.del_flag='0'
left join sys_dept d on d.dept_id=r.company_dept_id
r.is_current='1'
  and p.initiator_user_id=#{userId}
  and r.project_id=#{projectId}
  and r.company_dept_id=#{companyDeptId}
  and r.biz_date>=#{dateFrom}
  and r.biz_date<=#{dateTo}
 order by r.biz_date desc,r.profit_amount,r.project_id

select coalesce(sum(r.revenue_amount),0) revenueAmount,
  coalesce(sum(r.cost_amount),0) businessCost,
  coalesce(sum(r.personnel_cost),0) personnelCost,
  coalesce(sum(r.cost_amount+r.personnel_cost),0) costAmount,
  coalesce(sum(r.adjustment_amount),0) adjustmentAmount,coalesce(sum(r.profit_amount),0) profitAmount,
  count(distinct r.project_id) projectCount,count(*) resultCount
from biz_project_daily_result r join biz_project p on p.project_id=r.project_id and p.del_flag='0'
where r.is_current='1'
  and p.initiator_user_id=#{userId}
  and r.project_id=#{projectId}
  and r.company_dept_id=#{companyDeptId}
  and r.biz_date>=#{dateFrom}
  and r.biz_date<=#{dateTo}
